import assert from "node:assert/strict";
import { describe, it } from "node:test";
// @ts-expect-error contract.mjs is dynamically generated by test script
import { TimeLockedVaultContract } from "../../.test-build/contract.mjs";

const NOW = Date.parse("2026-09-20T12:00:00.000Z");
const DAY = 24 * 60 * 60 * 1000;

describe("Wave 2 end-to-end simulation", () => {
  function rejectsCode(fn: () => void, code: string) {
    try {
      fn();
    } catch (e: unknown) {
      const err = e as { code?: string };
      assert.equal(err.code, code);
      return;
    }
    assert.fail(`expected ${code}`);
  }

  it("strict: create → early reject → unlock withdraw", () => {
    const c = new TimeLockedVaultContract();
    c.initialize("treasury-wave2", "s-wave2");
    const v = c.createVault({ owner: "alice", asset: "NIGHT", amount: 1000n, unlockTime: NOW + DAY, lockType: "STRICT", penaltyBps: 0, now: NOW });
    rejectsCode(() => c.withdraw(v.id, "alice", "s-wave2", NOW + 1), "STILL_LOCKED");
    const r = c.withdraw(v.id, "alice", "s-wave2", NOW + DAY);
    assert.equal(r.ownerPayout, 1000n);
    assert.equal(r.penalty, 0n);
  });

  it("penalty: early exit pays bps to treasury", () => {
    const c = new TimeLockedVaultContract();
    c.initialize("treasury-wave2", "s-wave2");
    const v = c.createVault({ owner: "alice", asset: "NIGHT", amount: 10000n, unlockTime: NOW + DAY, lockType: "PENALTY", penaltyBps: 500, now: NOW });
    const r = c.withdrawWithPenalty(v.id, "alice", "s-wave2", NOW + 1, 500);
    assert.equal(r.penalty, 500n);
    assert.equal(r.ownerPayout, 9500n);
    assert.equal(c.getTreasury().balance, 500n);
  });
});
